"""Parse fixtures generated by Project-Limelight scripts/limelight_b2_upload.py.

These are synthetic sample values packed using the uploaded repository's real
serialization function; no real fleet measurements or secrets are included.
"""
from __future__ import annotations
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from limelight_parser import parse_content
from schema_tools import analyze_format

FIXTURES=Path(__file__).parent/'fixtures'

def _parse(name):
    return parse_content((FIXTURES/name).read_bytes(),f'limelight/v1/{name}')

def test_actual_source_cycle_mppt_and_peers():
    rows, errors=_parse('cycle_mppt.json.gz')
    assert not errors and len(rows)==1
    row=rows[0]
    assert row['node']=='32af66b77e9c'
    assert row['battery_voltage_v']==26.25
    assert row['pv_voltage_v']==44.1
    assert row['charge_current_a']==0.45
    assert row['solar_power_w']==38
    assert row['charger_state']==3
    assert row['thermal_mean_c']==47.2
    assert row['peer_ids']=='32dbd2292662'
    assert row['event']=='HOURLY_CYCLE'
    assert row['source'].endswith('.json.gz')

def test_actual_source_cycle_bench_no_mppt():
    rows, errors=_parse('cycle_bench.json.gz')
    row=rows[0]
    assert row['battery_explicit_null'] is True
    assert 'battery_voltage_v' not in row and 'solar_power_w' not in row
    assert row['energy_telemetry_status']=='unavailable'
    assert row['cycle_errors']=='battery_telemetry_unavailable'
    assert row['autonet_peer_count']==0
    assert row.get('peer_ids')==''

def test_actual_source_weekly():
    rows, errors=_parse('weekly.json.gz')
    assert not errors
    assert rows[0]['is_weekly']
    assert rows[0]['archive_week']=='2026-W40'
    assert rows[0]['archive_count']==4
    assert rows[0]['archive_warnings']==1

def test_schema_preserves_compressed_original_key():
    obj='limelight/v1/cycles/32af66b77e9c/2026/10/25/record.json.gz'
    schema=analyze_format((FIXTURES/'cycle_mppt.json.gz').read_bytes(),obj)
    assert schema and all(item['object']==obj for item in schema)
